        ContextSearchBodyMarkdownOptions out;
        out.extra_fields=wire::unknown(object, {"enabled", "includeLinks", "includeImages", "shortenBase64Images", "useMainContentOnly", "pdf", "includeFrames", "maxAgeMs", "waitForMs", "timeoutOpts"});
